-- Per-work cancellation (generated by drizzle-kit, reordered by hand so the composite unique keys
-- exist before the foreign keys that reference them, plus the backfill before the CHECKs).
CREATE TABLE "cancellation_items" (
	"order_item_id" uuid PRIMARY KEY NOT NULL,
	"cancellation_id" uuid NOT NULL,
	"order_id" uuid NOT NULL,
	"return_status" "return_status" DEFAULT 'NOT_APPLICABLE' NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL
);
--> statement-breakpoint
ALTER TABLE "cancellations" ADD COLUMN "requested_item_ids" uuid[];--> statement-breakpoint
ALTER TABLE "cancellations" ADD COLUMN "items_minor" integer;--> statement-breakpoint
ALTER TABLE "cancellations" ADD COLUMN "shipping_refund_minor" integer DEFAULT 0 NOT NULL;--> statement-breakpoint
ALTER TABLE "order_items" ADD CONSTRAINT "order_items_id_order_uq" UNIQUE("id","order_id");--> statement-breakpoint
ALTER TABLE "cancellations" ADD CONSTRAINT "cancellations_id_order_uq" UNIQUE("id","order_id");--> statement-breakpoint
ALTER TABLE "cancellation_items" ADD CONSTRAINT "cancellation_items_cancellation_fk" FOREIGN KEY ("cancellation_id","order_id") REFERENCES "public"."cancellations"("id","order_id") ON DELETE restrict ON UPDATE no action;--> statement-breakpoint
ALTER TABLE "cancellation_items" ADD CONSTRAINT "cancellation_items_order_item_fk" FOREIGN KEY ("order_item_id","order_id") REFERENCES "public"."order_items"("id","order_id") ON DELETE restrict ON UPDATE no action;--> statement-breakpoint
CREATE INDEX "cancellation_items_cancellation_idx" ON "cancellation_items" USING btree ("cancellation_id");--> statement-breakpoint
CREATE INDEX "cancellation_items_order_idx" ON "cancellation_items" USING btree ("order_id");--> statement-breakpoint
-- Backfill: a notice accepted before per-work cancellation covered every work of its order (and the
-- shipping). Only the earliest accepted or closed notice per order gets them: a work is cancelled
-- once. Closed duplicates were never accepted.
UPDATE "cancellations" c
   SET "items_minor" = o."items_total_minor",
       "shipping_refund_minor" = o."total_minor" - o."items_total_minor"
  FROM "orders" o
 WHERE o."id" = c."order_id"
   AND c."id" = (
     SELECT c2."id" FROM "cancellations" c2
      WHERE c2."order_id" = c."order_id"
        AND c2."status" IN ('ACCEPTED', 'CLOSED')
        AND c2."decision_reason" IS DISTINCT FROM 'DUPLICATE'
      ORDER BY c2."decided_at" NULLS LAST, c2."received_at", c2."id"
      LIMIT 1);--> statement-breakpoint
INSERT INTO "cancellation_items" ("order_item_id", "cancellation_id", "order_id", "return_status")
SELECT oi."id", c."id", c."order_id", c."return_status"
  FROM "cancellations" c
  JOIN "order_items" oi ON oi."order_id" = c."order_id"
 WHERE c."items_minor" IS NOT NULL;--> statement-breakpoint
ALTER TABLE "cancellations" ADD CONSTRAINT "cancellations_item_amounts_nonnegative" CHECK (("cancellations"."items_minor" IS NULL OR "cancellations"."items_minor" >= 0) AND "cancellations"."shipping_refund_minor" >= 0);--> statement-breakpoint
ALTER TABLE "cancellations" ADD CONSTRAINT "cancellations_refund_within_base" CHECK ("cancellations"."refund_amount_minor" IS NULL OR "cancellations"."items_minor" IS NULL OR "cancellations"."refund_amount_minor" + coalesce("cancellations"."fee_minor", 0) <= "cancellations"."items_minor" + "cancellations"."shipping_refund_minor");--> statement-breakpoint
CREATE UNIQUE INDEX "cancellations_one_shipping_refund_idx" ON "cancellations" USING btree ("order_id") WHERE "cancellations"."shipping_refund_minor" > 0 AND "cancellations"."status" IN ('ACCEPTED', 'CLOSED');
